793	    // g_next_task is UNTOUCHED (B2 reset it), so P3's drain is unchanged — no
794	    // sync_reset in P2.6.
795	    if constexpr (Opt == OptId::Prodigy) {
796	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
797	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
798	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
799	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
800	        const int64_t total_p = kVitTotalElems;
801	        const int64_t pbase = total_p / nCTA, prem = total_p % nCTA;
802	        const int64_t pe0 = (int64_t)cta * pbase + (cta < prem ? cta : prem);
803	        const int64_t pecnt = pbase + (cta < prem ? 1 : 0);
804	        float r_acc = 0.0f, s_acc = 0.0f;
805	        for (int64_t i = threadIdx.x; i < pecnt; i += blockDim.x) {
806	            algo::prodigy_partials_step(params, st.param_init, grad,
807	                                        d_prev, pe0 + i, r_acc, s_acc);
808	        }
809	        float r_block, s_block;
810	        prim::block_reduce_sum2_f32(r_acc, s_acc, r_block, s_block);
811	        if (threadIdx.x == 0) { r_part[cta] = r_block; s_part[cta] = s_block; }
812	        bar.sync();   // B2.6a: all per-CTA (r,s) partials published & visible
813	        if (cta == 0 && threadIdx.x == 0) {
814	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
815	            for (int c = 0; c < nCTA; ++c) { r_step += r_part[c]; s_step += s_part[c]; }
816	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
817	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
818	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
819	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
820	            st.prodigy_persist[1] = s_ema;
821	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
822	            d_bc[0]               = d_new;          // broadcast to all CTAs
823	        }
824	        bar.sync();   // B2.6b: d visible to every CTA before the apply
825	        st.d_factor = d_bc[0];                      // the reduced d the tail reads
826	    }
827	
828	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
829	    //    2D weights (INTEGRATION-OPTSTAGES §3). For EACH 2D matrix (kVitMuon2D) all
830	    //    CTAs cooperate: buf=μ·buf+g (buf is the PERSISTENT m-slice — momentum state,
831	    //    NOT transient), ‖buf‖_F via per-CTA partials → inv_norm, X=buf·inv_norm,
832	    //    then ns_steps × { A=XXᵀ → AX=A·X → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap },
833	    //    then the canonical muon_update_step apply (decay·p + neg_lr_scale·orth). The
834	    //    1D / non-2D weights (cls_token, biases, LN γ/β) take the AdamW tail in P3.
835	    //    The elementwise bodies CALL muon.h (muon_momentum_normalize_step via the
836	    //    phaseA buf body, muon_ns_combine_step, muon_update_step); the matmuls are the
837	    //    cited new device code (the eager path delegates to torch::mm/cuBLAS). Guarded
838	    //    so every other opt is byte-identical (no extra barriers / work).
839	    if constexpr (Opt == OptId::Muon) {
840	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
841	        PrecomputeWorkspace pw{};
842	        pw.muon_X            = muon_base;
843	        pw.muon_AX           = pw.muon_X   + kVitMuonMaxNumel;
844	        pw.muon_AAX          = pw.muon_AX  + kVitMuonMaxNumel;
845	        pw.muon_orth         = pw.muon_AAX + kVitMuonMaxNumel;
846	        pw.muon_A            = pw.muon_orth + kVitMuonMaxNumel;
847	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)kVitMuonMaxRows * kVitMuonMaxRows;
848	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
849	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
850	        const int   ns_steps = 5;                 // bindings.cpp default
851	        for (int mi = 0; mi < vittc::kVitNumMuon2D; ++mi) {
852	            const vittc::VitMuon2D M = vittc::kVitMuon2D[mi];
853	            const int rows = M.rows, cols = M.cols;
854	            const int64_t numel = (int64_t)rows * cols;
855	            const int64_t off   = (int64_t)kVitOffsets[M.tidx];
856	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
857	            pw.muon_buf = st.exp_avg + off;
858	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
859	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
860	            bar.sync();
861	            muon_norm_reduce_phaseB(ctx, pw);
862	            bar.sync();
863	            muon_scale_X(numel, pw);
864	            bar.sync();
865	            // NS iterations. After each combine, orth holds the new iterate; swap so
866	            // the next iteration reads it as X. ns_steps swaps → final result is in
867	            // muon_X iff ns_steps even else muon_orth (we track the parity below).
868	            for (int s = 0; s < ns_steps; ++s) {
869	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
870	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
871	                bar.sync();
872	                // AX = A X   (M=rows,N=cols,K=rows).
873	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
874	                bar.sync();
875	                // AAX = A (AX) (M=rows,N=cols,K=rows).
876	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
877	                bar.sync();
878	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
879	                bar.sync();
880	                // swap X <-> orth (next iter reads X; final result tracked by parity).
881	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
882	            }
883	            // After ns_steps swaps the final orthogonalized matrix is in muon_X (the
884	            // last combine wrote muon_orth, then we swapped → muon_X). Apply Muon:
885	            //   p = decay_factor·p + neg_lr_scale·orth   (muon.h:63-73)
886	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
887	            const float neg_lr_scale = -lr * scale;
888	            const float decay_factor = 1.0f - lr * st.wd;
889	            float* __restrict__ p = params + off;
890	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
891	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
892	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
893	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
894	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
895	        }
896	    }
