898	    // ── P2.45 (SuperGrok11/15 ONLY) staged into P3: the per-TENSOR meta-net mu
899	    //    precompute (INTEGRATION-OPTSTAGES §4/§5) — ViT twin of the decoder's. SINGLE
900	    //    task-queue drain, NO grid barrier (each tensor is self-contained: mu(T) +
901	    //    SG11's per-tensor cosine gate(T) depend ONLY on T's elements). The phi weights
902	    //    (per-TENSOR weight set) stage to SMEM ONCE per block before the drain; SG15's
903	    //    gate is the host scalar st.gate. sharpness was produced by P2.4 (or cached).
904	    __shared__ float sg_sW1[kSgPhiHidden * 2];
905	    __shared__ float sg_sb1[kSgPhiHidden];
906	    __shared__ float sg_sW2[kSgPhiHidden];
907	    if constexpr (Opt == OptId::SuperGrok11 || Opt == OptId::SuperGrok15) {
908	        sg_stage_phi_weights<kSgPhiHidden>(st.sg_phi_W1, st.sg_phi_b1, st.sg_phi_W2,
909	                                           sg_sW1, sg_sb1, sg_sW2);   // syncs
910	    }
911	
912	    // ── P3: scalar optimizer tail over the reduced grad (REUSED verbatim). ──
913	    st.lr = lr;
914	#ifdef SG_VIT_PROFILE
915	    unsigned long long _p3a = (threadIdx.x == 0) ? clock64() : 0;
916	#endif
917	    {
918	        __shared__ int task_slot;
919	        TaskQueue q = ctx.queue();
920	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
921	             t = q.next_block(&task_slot)) {
922	            const int n = kVitSizes[t];
923	            const int64_t off = (int64_t)kVitOffsets[t];
924	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
925	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
926	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
927	            if constexpr (Opt == OptId::Muon) {
928	                if (vittc::vit_is_muon_2d(t)) continue;
929	            }
930	            FusedOptState ts = vit_rebase_state<Opt>(st, off);
931	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
932	            //     t == the tensor's flat named_parameters() layer index (the
933	            //     work-steal task id maps 1:1 to kVitOffsets order == the eager
934	            //     enumeration order — cls_token is t=0). bc1 must be rebased TOO
935	            //     (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager; bc2 stays global.
936	            if constexpr (Opt == OptId::GrokAdamW) {
937	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
938	                ts.beta1 = b1;
939	                ts.bc1   = 1.0f - powf(b1, (float)step);
940	            }
941	            // SuperGrok11/15 meta-net mu (+ SG11 per-tensor gate) precompute for THIS
942	            // tensor, BEFORE the apply reads ts.mu/ts.gate (ViT twin of the decoder's).
943	            if constexpr (Opt == OptId::SuperGrok11) {
944	                const float b2 = (st.sg_phi_W2 != nullptr) ? st.sg_phi_W2[kSgPhiHidden]
945	                                                           : st.sg_phi_b2;
946	                const float g8 = sg11_precompute_mu_and_gate_for_tensor<kSgPhiHidden>(
947	                    st.mu, grad, st.sharpness, sg_sW1, sg_sb1, sg_sW2,
948	                    b2, st.sg_rescale, off, n);
949	                ts.gate = g8;            // per-tensor cosine gate the apply tail reads
950	                __syncthreads();         // mu(T) fully written + gate broadcast before apply
951	            } else if constexpr (Opt == OptId::SuperGrok15) {
952	                const float b2 = (st.sg_phi_W2 != nullptr) ? st.sg_phi_W2[kSgPhiHidden]
953	                                                           : st.sg_phi_b2;
954	                sg15_precompute_mu_for_tensor<kSgPhiHidden>(
955	                    st.mu, grad, st.sharpness, sg_sW1, sg_sb1, sg_sW2,
956	                    b2, st.sg_rescale, off, n);
957	                // ts.gate stays = st.gate (the host sigmoid(accuracy) scalar).
958	                __syncthreads();         // mu(T) visible before the apply reads it
959	            }
960	            float* __restrict__ p = params + off;
961	            const float* __restrict__ gg = grad + off;
962	            if constexpr (Opt == OptId::Muon) {
963	                // 1D / non-2D weights: the canonical AdamW tail (muon.py:115-125 routes
964	                // non-matrix params to a SEPARATE AdamW group with INDEPENDENT
965	                // hyperparameters — adamw_lr/adamw_betas — NOT the 2D Muon lr/momentum).
966	                // ts.lr/ts.beta1 carry the 2D-group's (lr=0.02, momentum=0.95), so the
967	                // 1D tail MUST instead use the aux_* fields (eager adamw_lr/adamw_betas).
968	                // weight_decay is SHARED across both eager groups (muon.py:122) → ts.wd
969	                // stays. eps is the eager adamw_eps (= ts.eps, mapped by _opt_scalars_from).
970	                // bc1/bc2 are device-computed here from aux_beta^step (kept out of the
971	                // mirror to shrink the host ABI surface; fp32 powf, tol 2e-3 is ample).
972	                // apply_optimizer<Muon> would deref st.orth (NS dir, only valid for 2D),
973	                // so route directly to adamw_step with the aux hyperparameters.
974	                const float a_bc1 = 1.0f - powf(st.aux_beta1, (float)step);
975	                const float a_bc2 = 1.0f - powf(st.aux_beta2, (float)step);
976	                for (int i = threadIdx.x; i < n; i += blockDim.x)
977	                    algo::adamw_step<float, float>(
978	                        p, ts.exp_avg, ts.exp_avg_sq, gg,
979	                        st.aux_lr, st.aux_beta1, st.aux_beta2, ts.eps, ts.wd,
980	                        a_bc1, a_bc2, (int64_t)i);
981	            } else {
982	                for (int i = threadIdx.x; i < n; i += blockDim.x)
983	                    apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
984	            }
985	        }
986	    }
987	#ifdef SG_VIT_PROFILE
988	    if (threadIdx.x == 0) { unsigned long long _p3b = clock64(); atomicMax(&g_vit_prof_max[5], _p3b - _p3a); }
989	#endif
990	}
