992	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
993	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas);
994	// any cap is hang-safe as long as the workspace + dW-tile/cls/pos ownership use
995	// the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
996	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
997	// scratch (nCTA × slab) fits. Determinism is preserved per fixed nCTA.
998	template <OptId Opt>
999	cudaError_t launch_fused_vit_megakernel_tc(
1000	        PersistentContext ctx, float* params, ViTInputCtx in,
1001	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
1002	        int ncta_cap = 0) {
1003	    int dev = 0;
1004	    cudaError_t err = cudaGetDevice(&dev);
1005	    if (err != cudaSuccess) return err;
1006	    int n_sms = 0;
1007	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1008	    if (err != cudaSuccess) return err;
1009	
1010	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
1011	    // (0 here — VitTcSmem is static). If the static smem + 200-reg consumer can't
1012	    // place one block/SM, REFUSE (the grid barrier would hang).
1013	    int occ = 0;
1014	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1015	        &occ, (const void*)&fused_vit_megakernel_tc<Opt>, SG_VIT_TC_MEGA_BLOCK,
1016	        /*dynamicSMemBytes=*/0);
1017	    if (err != cudaSuccess) return err;
1018	    if (occ < 1) return cudaErrorLaunchOutOfResources;
1019	
1020	    unsigned launch_ctas = (unsigned)n_sms;
1021	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
1022	    ctx.n_ctas = launch_ctas;
1023	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms).
1024	    if ((in.B % 16) != 0) return cudaErrorInvalidValue;
1025	
1026	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
1027	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
1028	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
1029	
1030	    dim3 grid(launch_ctas), block(SG_VIT_TC_MEGA_BLOCK);
1031	    fused_vit_megakernel_tc<Opt><<<grid, block, 0, stream>>>(
1032	        ctx, params, in, grad, lr, step, st);
1033	    return cudaGetLastError();
1034	}
